if [ "\$1" = "push" ] && [ -f "\$FA_RACE_FILE" ]; then
  race_left=\$(cat "\$FA_RACE_FILE")
  if [ "\$race_left" -gt 0 ]; then
    echo \$((race_left-1)) > "\$FA_RACE_FILE"
